\draw[line width=0.4pt] ($(P)!0.5!(Q)$)++({0.10*cos(80)},{-0.10*sin(80)})--++({-0.20*cos(80)},{0.20*sin(80)});
\draw[line width=0.4pt] (P)++(90:0.75) arc[start angle=90,end angle=70,radius=0.75];
\node[anchor=east] (givenAngle) at ($(P)+(-0.35,0.55)$) {$20^\circ$};
